#include <nlohmann/json.hpp>
#include <iostream>

int main() {
    try {
        std::string s = "{\"keep\": 1, \"drop\": 2, \"keep2\": 3}";
        auto cb = [](int, nlohmann::json::parse_event_t event, nlohmann::json & val) {
            if (event == nlohmann::json::parse_event_t::key && val == "drop") {
                return false;
            }
            return true;
        };
        nlohmann::json j = nlohmann::json::parse(s, cb);
        std::cout << j.dump() << std::endl;
    } catch (const std::exception& e) {
        std::cout << e.what() << std::endl;
    }
}
